@page "/recipes/{CuisineId:int}"
@using sv_5ae560020c754dd29e6f8353c805053d.Models
@using sv_5ae560020c754dd29e6f8353c805053d.Services
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav>
    <a href="/recipes/1?sort=@sort">Italian</a> |
    <a href="/recipes/2?sort=@sort">Indian</a> |
    <a href="/recipes/3?sort=@sort">Mexican</a>
</nav>

<div style="margin-top: 0.5rem;">
    Sort:
    <a href="@GetSortUrl("newest")">Newest</a> |
    <a href="@GetSortUrl("popular")">Popular</a>
    @if (!string.IsNullOrEmpty(sort))
    {
        <span> (sorted by @sort)</span>
    }
</div>

<hr />

@if (errorMessage is not null)
{
    <div role="alert" style="color: red; margin: 1rem 0;">
        <p>@errorMessage</p>
        <button @onclick="Retry">Retry</button>
    </div>
}
else if (recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    @if (recipes.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <ul>
            @foreach (var recipe in GetSortedRecipes())
            {
                <li>
                    <strong>@recipe.Title</strong> — @recipe.Description
                    <br />
                    <small>Prep time: @recipe.PrepTimeMinutes min</small>
                </li>
            }
        </ul>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? sort { get; set; }

    private List<Recipe>? recipes;
    private bool isRefreshing;
    private string? errorMessage;

    private int loadedCuisineId;
    private CancellationTokenSource? loadCts;

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == loadedCuisineId && recipes is not null)
        {
            // Only the sort parameter changed — no reload needed.
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for a previous cuisine.
        loadCts?.Cancel();
        loadCts?.Dispose();
        loadCts = new CancellationTokenSource();
        var cts = loadCts;

        errorMessage = null;
        isRefreshing = recipes is not null;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            if (cts.Token.IsCancellationRequested)
                return;

            recipes = result;
            loadedCuisineId = CuisineId;
            isRefreshing = false;
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Request was intentionally cancelled (navigation or new cuisine). Do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            isRefreshing = false;
            errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            isRefreshing = false;
            errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (recipes is null)
            return new();

        return sort?.ToLowerInvariant() switch
        {
            "newest" => recipes.OrderByDescending(r => r.Id).ToList(),
            "popular" => recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
            _ => recipes,
        };
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private string GetSortUrl(string sortValue)
    {
        return $"/recipes/{CuisineId}?sort={sortValue}";
    }

    public void Dispose()
    {
        loadCts?.Cancel();
        loadCts?.Dispose();
    }
}

